import pickle
import numpy as np
import os

def convert_smpl_pkl_to_npz(pkl_path, npz_path):
    \"\"\"Convert SMPL .pkl file to .npz format, replacing chumpy objects with numpy arrays.\"\"\"
    import warnings
    warnings.filterwarnings('ignore')

    with open(pkl_path, 'rb') as f:
        # First try to load with latin1 encoding
        try:
            data = pickle.load(f, encoding='latin1')
        except Exception as e:
            print(f'Error loading {pkl_path}: {e}')
            return False

    # Recursively replace chumpy arrays with numpy arrays
    def convert(obj):
        if hasattr(obj, 'd'):  # chumpy array-like object
            return np.array(obj)
        elif isinstance(obj, dict):
            return {k: convert(v) for k, v in obj.items()}
        elif isinstance(obj, (list, tuple)):
            return type(obj)(convert(i) for i in obj)
        elif hasattr(obj, '__iter__') and hasattr(obj, '__len__') and not isinstance(obj, (str, bytes)):
            try:
                return np.array(obj)
            except:
                return obj
        return obj

    converted_data = convert(data)

    # Save as npz
    np.savez(npz_path, **converted_data)
    print(f'Converted {pkl_path} -> {npz_path}')
    return True

